class CatalogCache:
    def __init__(self, catalog):
        self.catalog = catalog
        self.entries = {}
        self.versions = {}

    def get(self, id):
        current_version = self.catalog.versions.get(id, 0)
        if id not in self.entries or self.versions.get(id) != current_version:
            self.entries[id] = self.catalog.read(id)
            self.versions[id] = current_version
        value = self.entries[id]
        if value is None:
            return None
        return dict(value)

